"""Geometry / motion / slicing verification for the butterfly.  usage: verify.py OUTDIR"""
import sys, json, re, itertools, subprocess, numpy as np, trimesh, manifold3d as m3d
from shapely.geometry import Polygon, MultiPolygon, Point, LineString
from shapely.ops import unary_union
from scipy.spatial import cKDTree
OUT = sys.argv[1]
J = json.load(open(f"{OUT}/joints.json"))
parts = {p["name"]: trimesh.load(f"{OUT}/{p['file']}") for p in J["parts"]}
model = trimesh.load(f"{OUT}/model.stl")
joint = {j["child"]: j for j in J["joints"]}
R = {}

# ---------- 1. meshes / envelope ----------
R["parts"] = {n: dict(watertight=bool(m.is_watertight), winding_consistent=bool(m.is_winding_consistent),
                      shells=len(m.split(only_watertight=False)), volume_mm3=round(m.volume, 2),
                      bounds=m.bounds.round(3).tolist()) for n, m in parts.items()}
ext = model.bounds[1] - model.bounds[0]
R["model"] = dict(watertight=bool(model.is_watertight), shells=len(model.split(only_watertight=False)),
                  volume_mm3=round(model.volume, 2), sum_part_volumes=round(sum(m.volume for m in parts.values()), 2),
                  bounds=model.bounds.round(3).tolist(), size_xyz=ext.round(3).tolist(),
                  within_120x100x30=bool(ext[0] <= 120 and ext[1] <= 100 and ext[2] <= 30))

def mf(m): return m3d.Manifold(m3d.Mesh(vert_properties=np.asarray(m.vertices, np.float32), tri_verts=np.asarray(m.faces, np.uint32)))
def T(child, ang, shift=(0, 0, 0)):
    j = joint[child]; M = trimesh.transformations.rotation_matrix(np.radians(ang), j["axis"], j["origin"])
    M[:3, 3] += shift; return M
def posed(child, ang, shift=(0, 0, 0)): return parts[child].copy().apply_transform(T(child, ang, shift))
def inter(a, b): return (mf(a) ^ mf(b)).volume()

def sec_poly(m, z):
    s = m.section([0, 0, 1], [0, 0, z])
    if s is None: return Polygon()
    p2, M = s.to_2D(to_2D=np.eye(4))
    return unary_union(list(p2.polygons_full)).buffer(0)

# ---------- 2. motion sweep: exact boolean + per-layer 2D gaps ----------
zs = np.round(np.arange(0.1, 11.0, 0.2), 2)
names = ["body", "left_wing", "right_wing"]
def gaps(aL, aR):
    ms = {"body": parts["body"], "left_wing": posed("left_wing", aL), "right_wing": posed("right_wing", aR)}
    iv = {f"{a}|{b}": inter(ms[a], ms[b]) for a, b in itertools.combinations(names, 2)}
    g = {k: 1e9 for k in iv}
    for z in zs:
        P = {n: sec_poly(ms[n], z) for n in names}
        for a, b in itertools.combinations(names, 2):
            if not P[a].is_empty and not P[b].is_empty: g[f"{a}|{b}"] = min(g[f"{a}|{b}"], P[a].distance(P[b]))
    return iv, g
sweep = []; worst = {}
grid = [-30, -20, -10, 0, 10, 20, 30]
cases = [(a, 0) for a in range(-30, 31, 5)] + [(0, a) for a in range(-30, 31, 5)] + list(itertools.product(grid, grid))
for aL, aR in sorted(set(cases)):
    iv, g = gaps(aL, aR)
    sweep.append(dict(left=aL, right=aR, max_intersection_mm3=max(iv.values()), min_layer_gap={k: round(v, 3) for k, v in g.items()}))
    for k in g: worst[k] = min(worst.get(k, 1e9), g[k])
R["motion_sweep"] = dict(cases=len(sweep), max_intersection_mm3=max(s["max_intersection_mm3"] for s in sweep),
                         min_xy_gap_over_all_cases={k: round(v, 3) for k, v in worst.items()}, detail=sweep)

# 3D clearance away from the pin/bore (cones give the vertical gaps; KD-tree on dense samples)
def samp(m, n=250000): return np.vstack([trimesh.sample.sample_surface(m, n, seed=1)[0], m.vertices])
def rloc(p, child): o = np.array(joint[child]["origin"]); return np.hypot(p[:, 0] - o[0], p[:, 1] - o[1])
Bp = samp(parts["body"]); tree = cKDTree(Bp)
d3 = {}
for child in ["left_wing", "right_wing"]:
    Wl = samp(parts[child]); mn = 1e9; mn_far = 1e9
    for a in range(-30, 31, 5):
        Wp = trimesh.transform_points(Wl, T(child, a)); d, i = tree.query(Wp)
        mn = min(mn, d.min())
        far = (rloc(Wp, child) > 6.0) | (rloc(Bp[i], child) > 6.0)
        mn_far = min(mn_far, d[far].min())
    d3[child] = dict(min_3d_gap_any=round(mn, 3), min_3d_gap_outside_pin_bore=round(mn_far, 3))
R["clearance_3d_sampled"] = d3

# ---------- 3. hard stops & independence ----------
def first_contact(child, sgn):
    a = 30.0
    while a < 90:
        if inter(parts["body"], posed(child, sgn * a)) > 1e-3: return a
        a += 0.5
    return None
R["hard_stop_deg"] = {c: dict(neg=first_contact(c, -1), pos=first_contact(c, +1)) for c in ["left_wing", "right_wing"]}

# ---------- 4. axial / radial retention (how far can the wing translate before it hits the body) ----------
def free_travel(child, direction, lim=10.0):
    d = np.array(direction, float); lo, hi = 0.0, lim
    if inter(parts["body"], posed(child, 0, d * hi)) < 1e-4: return None   # escapes
    for _ in range(14):
        mid = (lo + hi) / 2
        if inter(parts["body"], posed(child, 0, d * mid)) > 1e-4: hi = mid
        else: lo = mid
    return round(hi, 3)
ret = {}
for c in ["left_wing", "right_wing"]:
    s = 1 if c == "left_wing" else -1
    ret[c] = {"+Z": free_travel(c, (0, 0, 1)), "-Z": free_travel(c, (0, 0, -1)),
              "outboard": free_travel(c, (0, s, 0)), "+X": free_travel(c, (1, 0, 0)), "-X": free_travel(c, (-1, 0, 0))}
R["retention_free_travel_mm"] = ret

# ---------- 5. pin / bore radial clearance from sections ----------
pc = {}
for c in ["left_wing", "right_wing"]:
    o = np.array(joint[c]["origin"][:2]); rows = []
    for z in [0.1, 1.0, 2.0, 2.6, 3.4, 4.5, 5.5, 6.5, 6.9]:
        pb = sec_poly(parts["body"], z).intersection(Point(o).buffer(5.2))
        pw = sec_poly(parts[c], z).intersection(Point(o).buffer(8.0))
        r_pin = max(np.hypot(*(np.array(g.exterior.coords) - o).T).max() for g in getattr(pb, "geoms", [pb]))
        # bore radius: nearest wing boundary to the axis
        r_bore = min(Point(o).distance(g.exterior) for g in getattr(pw, "geoms", [pw]))
        rows.append(dict(z=z, pin_r=round(r_pin, 3), bore_r=round(r_bore, 3), radial_gap=round(r_bore - r_pin, 3),
                         polygon_gap=round(pb.distance(pw), 3)))
    pc[c] = rows
R["pin_bore_sections"] = pc

# ---------- 6. overhangs (downward faces steeper than 45 deg from vertical, above the bed) ----------
oh = {}
for n, m in parts.items():
    nz = m.face_normals[:, 2]; zc = m.triangles_center[:, 2]; A = m.area_faces
    above = zc > 0.05
    steep = above & (nz < -np.cos(np.radians(45)) - 1e-3)
    any_down = above & (nz < -0.05)
    oh[n] = dict(steep_overhang_area_mm2=round(A[steep].sum(), 3),
                 max_overhang_from_vertical_deg=round(float(np.degrees(np.arccos(np.clip(-nz[any_down], -1, 1))).min() * -1 + 90 + 0), 2) if any_down.any() else 0,
                 down_facing_area_mm2=round(A[any_down].sum(), 2))
    # max overhang angle measured from vertical (0 = vertical wall, 90 = flat ceiling)
    oh[n]["max_overhang_from_vertical_deg"] = round(float(np.degrees(np.arcsin(np.clip(-nz[any_down], 0, 1))).max()), 2) if any_down.any() else 0
R["overhangs"] = oh
json.dump(R, open("/tmp/work/verify_geom.json", "w"), indent=1)
print(json.dumps({k: v for k, v in R.items() if k != "motion_sweep"}, indent=1))
print(json.dumps({k: v for k, v in R["motion_sweep"].items() if k != "detail"}, indent=1))
